var documenterSearchIndex = {"docs":
[{"category":"section","location":"example_junction/#Example-of-a-junction-with-N-bonds","page":"Example: Single junction","text":"using CellAdhesion\n\nPlots needs to be installed to run these examples and display plots of the data.\n\nusing Plots\nusing Statistics","title":"Example of a junction with N bonds"},{"category":"section","location":"example_junction/#Slip-bond-model","page":"Example: Single junction","text":"","title":"Slip bond model"},{"category":"section","location":"example_junction/#Example-with-constant-force","page":"Example: Single junction","text":"Define the parameters for the Slip bond model for the junction\nGenerate a junction made of N bonds\nRun the simulations for the junction subjected to a constant force within the range 2-10, 50 times for each level of force\n\nDefine the BondModel to compute the binding-unbinding rate\n\nmodel = SlipBondModel((k_on_0=3e-3,), (k_off_0=3e-4, f_1e=0.055))\nBondModel{Slip}((k_on = 0.003f0, k_off_0 = 0.0003f0, f_1e = 0.055f0))\n\nDefine the Cluster data structure parameters\n\nN = 25;      # Number of bonds\nl = 1.0;     # Distance between bonds\n\nDefine the range of constant forces to be applied\n\nF = [2.0, 2.5, 3.0, 3.5, 4.0, 4.5, 5.0];\n\nRun the Montecarlo simulations for different level of forces, n times each\n\nn = 10;            # Number of simulations\nn_f = length(F);    # Number of different forces to apply to the junction\n\ntime_break_F = zeros(n_f)  # Vector with mean rupture time for the different applied forces\n\np = plot()\n\n# For loop on the applied Force (F)\nfor j = 1:1:n_f\n\n    stress_break_v = zeros(n)\n    time_break_v = zeros(n)\n\n    # For loop on the different simulations for each scenario (n)\n    for sim = 1:1:n\n\n        # Initiate the junction (Cluster data structure)\n        x = Cluster(N, l, model, :force_global)\n\n        # Run the Montecarlo simulation until it breaks or it reaches the maximum number of iterations\n        state, stress_break_v[sim], time_break_v[sim], step = runcluster(x, F[j], 0.01, max_steps = 500000)\n\n    end\n\n    # Plot all rupture time for all the simulations\n    scatter!(p, repeat([F[j]],n), time_break_v, label = \"\", mc=\"#1E88E5\", ms=4, ma=1)\n\n    # Compute the mean rupture time\n    time_break_F[j] = mean(time_break_v)\nend\n\nPlot the average rupture time as a function of the applied force\n\nscatter!(p, F.+0.1, time_break_F, label=\"Mean\", mc=\"#D81B60\", ms=4, ma=1)\nxlabel!(\"Force (N)\")\nylabel!(\"Time (s)\")\nPlot{Plots.GRBackend() n=8}","title":"Example with constant force"},{"category":"section","location":"example_junction/#Example-with-varing-force-(linear-force-variation)","page":"Example: Single junction","text":"We define force ramps with different deformation rates (0.5%/s, 1%/s, 2%/s, 3%/s)\n\nrates = [0.005, 0.01, 0.02, 0.03]\nk = 1   # Spring stiffness\n1\n\nRun the Montecarlo simulations for different ramps, n times each\n\nn = 20;            # Number of simulations\nn_f = length(rates);    # Number of different forces to apply to the junction\n\ntime_break_F = zeros(n_f)  # Vector with mean rupture time for the different rates of application\nstress_break_F = zeros(n_f)  # Vector with mean rupture stress for the different rates of application\n\np1 = plot()\np2 = plot()\n\n# For loop on the applied Force (F)\nfor j = 1:1:n_f\n\n    stress_break_v = zeros(n)\n    time_break_v = zeros(n)\n\n    # Generate the force vector\n    t = collect(LinRange(0,6000,600001))\n    ϵ = rates[j] .* t;\n\n    f = k .* ϵ\n\n    # For loop on the different simulations, for each scenario (n)\n    for sim = 1:1:n\n\n        # Initiate the junction (Cluster data structure)\n        x = Cluster(N, l, model, :force_global)\n\n        # Run the Montecarlo simulation until it breaks or it reaches the maximum number of iterations\n        state, stress_break_v[sim], time_break_v[sim], step = runcluster(x, f, 0.01, max_steps = 500000)\n\n    end\n\n    # Plot all rupture time for all the simulations\n    scatter!(p1, repeat([rates[j]*100],n), time_break_v, label = \"\", mc=\"#1E88E5\", ms=4, ma=1)\n    scatter!(p2, repeat([rates[j]*100],n), stress_break_v, label = \"\", mc=\"#1E88E5\", ms=4, ma=1)\n\n    # Compute the mean rupture time\n    time_break_F[j] = mean(time_break_v)\n    stress_break_F[j] = mean(stress_break_v)\nend\n\nPlot the average rupture time as a function of the applied force\n\nscatter!(p1, (rates.+0.001)*100, time_break_F, label=\"Mean\", mc=\"#D81B60\", ms=4, ma=1)\nxlabel!(\"Rate (%/s)\")\nylabel!(\"Time (s)\")\n\nscatter!(p2, (rates.+0.001)*100, stress_break_F, label=\"Mean\", mc=\"#D81B60\", ms=4, ma=1)\nxlabel!(\"Rate (%/s)\")\nylabel!(\"Force (N)\")\n\nplot!(p1,p2)\nPlot{Plots.GRBackend() n=10}","title":"Example with varing force (linear force variation)"},{"category":"section","location":"example_junction/#Catch-bond-model","page":"Example: Single junction","text":"","title":"Catch bond model"},{"category":"section","location":"example_junction/#Example-with-constant-force-2","page":"Example: Single junction","text":"Define the BondModel to compute the binding-unbinding rate\n\nmodel = CatchBondModel((k_on_0 = 0.5,), (k_off_0s = 1e-4, f_1es = 1.0, k_off_0c = 1e-2, f_1ec = 1.0))\nBondModel{Catch}((k_on = 0.5f0, k_off_0s = 0.0001f0, f_1es = 1.0f0, k_off_0c = 0.01f0, f_1ec = 1.0f0))\n\nDefine the Cluster data structure parameters\n\nN = 20;      # Number of bonds\nl = 1.0;     # Distance between bonds\n\nDefine the range of constant forces to be applied\n\nF = collect(105.0:120.0);\n\nRun the Montecarlo simulations for different level of forces, n times each\n\nn = 10;            # Number of simulations\nn_f = length(F);    # Number of different forces to apply to the junction\n\ntime_break_F = zeros(n_f)  # Vector with mean rupture time for the different applied forces\n\np = plot()\n\n# For loop on the applied Force (F)\nfor j = 1:1:n_f\n\n    stress_break_v = zeros(n)\n    time_break_v = zeros(n)\n\n    # For loop on the different simulations for each scenario (n)\n    for sim = 1:1:n\n\n        # Initiate the junction (Cluster data structure)\n        x = Cluster(N, l, model, :force_global)\n\n        # Run the Montecarlo simulation until it breaks or it reaches the maximum number of iterations\n        state, stress_break_v[sim], time_break_v[sim], step = runcluster(x, F[j], 0.01, max_steps = 500000)\n\n    end\n\n    # Plot all rupture time for all the simulations\n    scatter!(p, repeat([F[j]],n), time_break_v, label = \"\", mc=\"#1E88E5\", ms=4, ma=1)\n\n    # Compute the mean rupture time\n    time_break_F[j] = mean(time_break_v)\nend\n\nPlot the average rupture time as a function of the applied force\n\nscatter!(p, F.+0.1, time_break_F, label=\"Mean\", mc=\"#D81B60\", ms=4, ma=1)\nxlabel!(\"Force (N)\")\nylabel!(\"Time (s)\")\ntitle!(\"Catch bond model - constant force\")\nPlot{Plots.GRBackend() n=17}\n\n\n\nThis page was generated using Literate.jl.","title":"Example with constant force"},{"category":"section","location":"architecture/#Architecture","page":"Architecture","text":"CellAdhesion is built around three main data types:\n\nBond: it is a mutable structure that contains information regarding the state of the bond (open = false or closed = true), the force applied to the bond (f), the model that discribes the dynamics of the bond (binding-unbinding probabilities).\nCluster: it is a mutable structure that contains a unit element vector (this can be of type Bond if the junction is made of one bond cluster, or Cluster if the junction is made of clusters), the state of the cluster (open = false, closed = true), the force applied to the Cluster (f), the model by which the force is distributed within bonds (f_model), the number of unit elements (n), the distance between unit elements (l). ","title":"Architecture"},{"category":"section","location":"example_junction_with_stress_from_file/","page":"-","text":"using CellAdhesion\nusing DelimitedFiles\nusing Plots\nusing Statistics\n\nfind all the files in the data directory\n\ndata_dir_candidates = [\n    joinpath(@__DIR__, \"example_data\"),\n    joinpath(pkgdir(CellAdhesion), \"docs\", \"src\", \"example_data\"),\n]\ndata_dir_idx = findfirst(isdir, data_dir_candidates)\ndata_dir_idx === nothing && error(\"Could not locate example_data directory\")\ndata_dir = data_dir_candidates[data_dir_idx]\nfiles = readdir(data_dir)\n9-element Vector{String}:\n \"stress_strain_Nonlinear_maxwell_1.0.txt\"\n \"stress_strain_Nonlinear_maxwell_10.0.txt\"\n \"stress_strain_Nonlinear_maxwell_100.0.txt\"\n \"stress_strain_Nonlinear_maxwell_20.0.txt\"\n \"stress_strain_Nonlinear_maxwell_3.0.txt\"\n \"stress_strain_Nonlinear_maxwell_30.0.txt\"\n \"stress_strain_Nonlinear_maxwell_5.0.txt\"\n \"stress_strain_Nonlinear_maxwell_50.0.txt\"\n \"stress_strain_Nonlinear_maxwell_7.0.txt\"\n\nextract the strain rates from the file names\n\nstrain_rates = [parse(Float64, split(split(file, \"_\")[end], \".txt\")[1]) for file in files]\n9-element Vector{Float64}:\n   1.0\n  10.0\n 100.0\n  20.0\n   3.0\n  30.0\n   5.0\n  50.0\n   7.0\n\nreorder file names based on increasing strain rates\n\nsorted_idx = sortperm(strain_rates)\nfiles = files[sorted_idx]\nstrain_rates = strain_rates[sorted_idx]\n9-element Vector{Float64}:\n   1.0\n   3.0\n   5.0\n   7.0\n  10.0\n  20.0\n  30.0\n  50.0\n 100.0\n\nDefine the bond model (slip bond model)\n\nmodel = SlipBondModel((k_on_0=3e-3,), (k_off_0=3e-4, f_1e=0.055))\nBondModel{Slip}((k_on = 0.003f0, k_off_0 = 0.0003f0, f_1e = 0.055f0))\n\nDefine simulation parameters\n\nN = 20               # Number of bonds in the junction\nl = 1.0               # Distance between bonds\n1.0\n\nRun the Montecarlo simulations for the different files, 50 times each\n\nn = 50                      # Number of simulations for each strain rate\nn_f = length(strain_rates)  # Number of different strain rates to apply to the junction\n9\n\nrun simulation for each strain rate and save the results in a dictionary\n\ntime_break = zeros(n_f)\nstress_break = zeros(n_f)\nstrain_break = zeros(n_f)\n\np1 = plot()\np2 = plot()\np3 = plot()\nfor (i, strain_rate) in enumerate(strain_rates)\n    # load the stress-time data from the file\n    data = readdlm(joinpath(data_dir, files[i]))\n    time = data[2:end, 1]   # ignore the header\n    strain = data[2:end, 2]\n    stress = data[2:end, 3]\n    dt = time[2] - time[1]  # Calculate time step from the data\n    max_steps = length(time)  # Set max_steps based on the length of the time data\n\n    # convert stress to tension\n    tension = stress .* N .* l  # Assuming stress is per bond, multiply by number of bonds and distance to get tension\n\n    tension_break_v = zeros(n)\n    time_break_v = zeros(n)\n    strain_break_v = zeros(n)\n\n    for repeat in 1:n\n        # Define the junction\n        x = Cluster(N, l, model, :force_global)\n\n        # Run the simulation\n        state, tension_break_v[repeat], time_break_v[repeat], step = runcluster(x, tension, dt; max_steps=max_steps, verbose=true)\n    end\n    tension_break_v /= N*l # Convert tension back to stress for plotting\n    strain_break_v = [strain[argmin(abs.(time .- time_break_v[i]))] for i in 1:n]\n\n    # Scatter plot of rupture times for the current strain rate\n    scatter!(p1, strain_break_v, tension_break_v , label=\"\", mc=\"#1E88E5\", ms=4, ma=1)\n    scatter!(p2, repeat([strain_rate], n), time_break_v, label=\"\", mc=\"#1E88E5\", ms=4, ma=1)\n    scatter!(p3, repeat([strain_rate], n), tension_break_v , label=\"\", mc=\"#1E88E5\", ms=4, ma=1)\n\n    # add the stress-strain curve for the current strain rate\n    plot!(p1, strain, stress, label=\"\", lw=2, color=:grey)\n\n    # compute the means\n    time_break[i] = mean(time_break_v)\n    stress_break[i] = mean(tension_break_v)\n    strain_break[i] = mean(strain_break_v)\nend\n\nscatter!(p1, strain_break, stress_break, label=\"Mean\", mc=\"#D81B60\", ms=4, ma=1)\nscatter!(p2, strain_rates, time_break, label=\"Mean\", mc=\"#D81B60\", ms=4, ma=1)\nscatter!(p3, strain_rates, stress_break, label=\"Mean\", mc=\"#D81B60\", ms=4, ma=1)\nplot!(p1, xlabel=\"Strain\", ylabel=\"Rupture Stress (\\$N/m^2\\$)\")\nplot!(p2, xlabel=\"Strain Rate (1/s)\", ylabel=\"Rupture Time (s)\", yscale=:log10, xscale=:log10)\nplot!(p3, xlabel=\"Strain Rate (1/s)\", ylabel=\"Rupture Stress (\\$N/m^2\\$)\", yscale=:log10, xscale=:log10)\n\nplot!(p1, strain_break, stress_break, label=\"\", c=\"#D81B60\", linewidth=3, linestyle=:dash)\n\nplot(p1, p2, p3, layout=(1,3), size=(1200,400), margin=5Plots.mm)\nPlot{Plots.GRBackend() n=40}\n\n\n\nThis page was generated using Literate.jl.","title":"-"},{"category":"section","location":"","page":"Home","text":"﻿<a name=\"logo\"/> <div align=\"center\"> <img src=\"https://raw.githubusercontent.com/ComputationalMechanobiology/CellAdhesion.jl/master/docs/src/assets/logo_colour.png\" height=\"70\"></img> </a> </div> <!– delim –>","title":"Home"},{"category":"section","location":"#CellAdhesion","page":"Home","text":"Tests Documentation Coverage\n(Image: Runtests) (Image: Development Documentation) (Image: codecov)\n\nCellAdhesion is a software package written in the Julia programming language that provides tools for modeling binding-unbinding dynamics of cell adhesion molecules. Features include:\n\nJunctions life-span can be computed for different loading histories\nDifferent models for computing the binding and unbinding probabilities are implemented\nJunctions with different adhesion molecules, thus bonds with different properties, can be modeled\nDynamics of junctions with bond clusters can be implemented","title":"CellAdhesion"},{"category":"section","location":"API/#API","page":"API","text":"","title":"API"},{"category":"section","location":"API/#Main-CellAdhesion-data-structures","page":"API","text":"","title":"Main CellAdhesion data structures"},{"category":"section","location":"API/#Processing-functions","page":"API","text":"","title":"Processing functions"},{"category":"section","location":"API/#Utility-functions","page":"API","text":"","title":"Utility functions"},{"category":"section","location":"API/#Serialization-internals","page":"API","text":"","title":"Serialization internals"},{"category":"section","location":"API/#Dynamics-functions","page":"API","text":"","title":"Dynamics functions"},{"category":"type","location":"API/#CellAdhesion.Bond","page":"API","text":"Bond\nBond(state::{Bool}, f::{CellAdhesionFloat}, model)\n\n`Bond` struct contains sate, force and model of a single bond\n\n# Fields\n\n- `state`: false (0)  = open, true (1) = closed\n- `f`: force\n- `t`: time\n- `model`: BondModel describing the bond binding-unbinding dynamics\n\n\n\n\n\n","title":"CellAdhesion.Bond"},{"category":"type","location":"API/#CellAdhesion.Cluster","page":"API","text":"Cluster(u::Vector{Bond,Cluster}, state::{Bool}, f::{CellAdhesionFloat}, f_model::{Symbol}, n::{CellAdhesionInt}, l::{CellAdhesionFloat})\n\n\n\n\n\n","title":"CellAdhesion.Cluster"},{"category":"function","location":"API/#CellAdhesion.update!","page":"API","text":"update!(v, dt)\n\nUpdates the state of an interface (that can be made of bonds or it can be a hierarchical structure).\n\nInput parameters:\n\nv: interface (this can be a cluster or a bond)\ndt: time step of the simulation\n\n\n\n\n\n","title":"CellAdhesion.update!"},{"category":"function","location":"API/#CellAdhesion.runcluster","page":"API","text":"runcluster(v, force, dt::Float64; max_steps::Integer = 1000, verbose::Bool = false)\n\nSimulates a junction subjected to an external force using a Montecarlo algorithm. \n\nInput paramters:\n\nv: structure of type Cluster\nforce: it can either be an constant number (if the junction is subjected to a constant force), or a vector (if the junction is subjected to a varing force)\ndt: time step for the simulation\nmax_steps: maximum number of iterations if the junction doesn't break\n\nOutput paramters:\n\nstate of the whole Cluster \nforce at which it breaks\ntime at which it breaks\nnumber of steps after which it breaks\n\n\n\n\n\n","title":"CellAdhesion.runcluster"},{"category":"function","location":"API/#CellAdhesion.bond_state_force","page":"API","text":"bondstateforce(v; output=:flat, time=missing)\n\nReturn bond state/force information for a Bond, a Cluster{Bond}, or nested Cluster.\n\noutput=:flat (default) returns tuples (states, forces).\noutput=:nested returns a Dict(time => force_tree) representation of the hierarchy, where each cluster level stores [cluster_force, child_forces].\n\nClosed bonds are assigned NaN in the force output.\n\n\n\n\n\n","title":"CellAdhesion.bond_state_force"},{"category":"function","location":"API/#CellAdhesion.save_cluster_to_json","page":"API","text":"saveclusterto_json(cluster::Cluster, filename::String)\n\nSave all parameters of a cluster (or cluster of clusters) to a JSON file.\n\nExample:\n\nmodel = SlipBondModel((k_on_0=1.0,), (k_off_0=2.0, f_1e=3.0))\ncluster = Cluster(5, 1.0, model, :force_global)\nsave_cluster_to_json(cluster, \"cluster_params.json\")\n\n\n\n\n\n","title":"CellAdhesion.save_cluster_to_json"},{"category":"function","location":"API/#CellAdhesion.load_from_json","page":"API","text":"loadfromjson(filename::String, load_force::Bool)::Cluster\n\nLoad a cluster (and force) from a JSON file that was saved with saveclusterto_json/.\n\nExample:\n\ncluster = load_from_json(\"cluster_params.json\", false)\n\n\n\n\n\n","title":"CellAdhesion.load_from_json"},{"category":"function","location":"API/#CellAdhesion.state!","page":"API","text":"state!(v)\n\nUpdates the state field of a Cluster or a Bond. When all the subunits are open, then the state of the structure is set to open. Otherwise, it is close.\n\nInput parameters:\n\nv: interface that can either be a Cluster or a Bond.\n\nOutput:   State of the cluster/bond, false for broken, true otherwise.\n\n\n\n\n\n","title":"CellAdhesion.state!"},{"category":"function","location":"API/#CellAdhesion.print_cluster","page":"API","text":"print_cluster(x)\n\nNice screen print of Cluster structure or Bond (x)\n\n\n\n\n\n","title":"CellAdhesion.print_cluster"},{"category":"function","location":"API/#CellAdhesion._save_bond_to_dict","page":"API","text":"savebondtodict(bond::Bond)::Dict\n\nSerialize a Bond's parameters to a dictionary. Includes model type, and all model parameters. Handles NaN values by converting them to the string \"nan\" for JSON compatibility.\n\n\n\n\n\n","title":"CellAdhesion._save_bond_to_dict"},{"category":"function","location":"API/#CellAdhesion._save_cluster_to_dict","page":"API","text":"saveclustertodict(cluster::Cluster)::Dict\n\nRecursively serialize a Cluster's parameters to a dictionary. Includes cluster-level parameters (f_model, n, l) and recursively saves all children (which can be Bonds or nested Clusters).\n\n\n\n\n\n","title":"CellAdhesion._save_cluster_to_dict"},{"category":"function","location":"API/#CellAdhesion._load_bond_from_dict","page":"API","text":"loadbondfromdict(bond_dict::Union{Dict, AbstractDict})::Bond\n\nDeserialize a Bond from a dictionary. Reconstructs the BondModel with the correct type and parameters.\n\n\n\n\n\n","title":"CellAdhesion._load_bond_from_dict"},{"category":"function","location":"API/#CellAdhesion._load_cluster_from_dict","page":"API","text":"loadclusterfromdict(cluster_dict::Union{Dict, AbstractDict})::Cluster\n\nRecursively deserialize a Cluster from a dictionary. Reconstructs the complete cluster hierarchy by recursively loading children (which can be Bonds or nested Clusters).\n\n\n\n\n\n","title":"CellAdhesion._load_cluster_from_dict"},{"category":"function","location":"API/#CellAdhesion.setforce!","page":"API","text":"setforce!(v::Cluster{Bond{T}}, F::CellAdhesionFloat)\n\nInput parameters:\n\nv: Cluster structure\nF: Force applied to the cluster\n\nOutput parameters:\n\nUpdated the force applied to each Cluster structure (within the hierarchical structure)\n\n\n\n\n\n","title":"CellAdhesion.setforce!"},{"category":"function","location":"API/#CellAdhesion.force_global","page":"API","text":"force_global(v::Cluster)\n\nComputer force distribution by equally dividing the force within the closed bonds\n\n\n\n\n\n","title":"CellAdhesion.force_global"},{"category":"function","location":"API/#CellAdhesion.force_local","page":"API","text":"force_local(v::Cluster)\n\nComputer force distribution by accounting for the distance of each link from its two closest neighbours\n\n\n\n\n\n","title":"CellAdhesion.force_local"},{"category":"function","location":"API/#CellAdhesion.distance","page":"API","text":"distance(v::BitVector, n::Integer)\n\nCompute the distance of each from its two closest closed link on each side.  Used to compute a \"local\" load distributions across closed bonds. Periodic bondary conditions for the edges.\n\nInput parameters:\n\nv: vector with the state of each single bond\nn: number of bonds in the interface\n\nOutput parameters:\n\nl: vector of CellAdhesionFloat containing the distance for each closed bond\n\n\n\n\n\n","title":"CellAdhesion.distance"}]
}
